import { CWSNService } from './../../../services/cwsn.service';
import { Component, OnInit } from '@angular/core';
import { AlertService } from 'src/app/services/alert.service';
import { ActivatedRoute, Router } from '@angular/router';
import { SqlitedatabaseService } from 'src/app/services/sqlite/sqlitedatabase.service';
@Component({
  selector: 'app-class-list2',
  templateUrl: './class-list2.page.html',
  styleUrls: ['./class-list2.page.scss'],
})
export class ClassList2Page implements OnInit {
  schoolId: any;
  routeData: any;
  classId: any;
  sectionId: any;
  sectionArr: any[] = [];
  class_data: any;
  tablename: string;
  studentData: any[];

  constructor(
    private cwsnService: CWSNService,
    private alertService: AlertService,
    private route: ActivatedRoute,
    private router: Router,
    private sqliteDB: SqlitedatabaseService
  ) { }

  ngOnInit() {

  }

  ionViewDidEnter() {
    this.route.queryParams.subscribe(data => {
      if (data) {
        debugger
        if (data.data) {
          let value = JSON.parse(data.data);
          this.routeData = value;
          this.class_data = this.routeData.classData;
          this.classId = this.routeData.clsSec.Class;
          this.schoolId = this.routeData.schoolId.SchlId;
          this.checkLocalStuList();
        }
      }
    })
  }

  checkLocalStuList() {
    this.tablename = 'AllClasslist';
    this.sqliteDB.checkDataExistsWithConditions(this.tablename, "SchlD", this.schoolId).then((res) => {
      if (res == true) {
        this.checkLocalDB();
      } else {
        this.ionViewDidEnter()
        // this.sharedService.onClassStudentStaffList(this.schoolId);
      }
    })
  }

  checkLocalDB() {
    let sec_query = 'SELECT * FROM cwsn_student_list' +
      ' WHERE school_key_id = "' + this.schoolId + '"' +
      ' And Class = "' + this.classId + '" ';

    this.sqliteDB.executeQuery(sec_query).then(res => {
      if (res.rows.length > 0) {
        let sec_temp = [];
        for (var j = 0; j < res.rows.length; j++) {
          sec_temp.push(res.rows.item(j));
        };
        this.studentData = sec_temp;

        let query = 'SELECT * FROM cwsn_sec_list' +
          ' WHERE school_key_id = "' + this.schoolId + '"' +
          ' And Class = "' + this.classId + '" ';
        this.sqliteDB.executeQuery(query).then(res => {
          if (res.rows.length > 0) {
            let temp = [];
            for (var i = 0; i < res.rows.length; i++) {
              temp.push(res.rows.item(i));
            };
            this.sectionArr = temp;
            for (let i = 0; i < this.sectionArr.length; i++) {

              let tot = 0;
              let Scrn = 0;
              let Unscrn = 0;

              let sec_total_filter = this.studentData.filter(obj => obj.Class == this.sectionArr[i].Class && obj.Sec == this.sectionArr[i].Sec && obj.cwsnStatus != null );

              let sec_scrn_filter = this.studentData.filter(obj => obj.Class == this.sectionArr[i].Class && obj.Sec == this.sectionArr[i].Sec && obj.cwsnStatus != null && (obj.ScrSts != null && obj.ScrSts != ''));

              let sec_unscrn_filter = this.studentData.filter(obj => obj.Class == this.sectionArr[i].Class && obj.Sec == this.sectionArr[i].Sec && obj.cwsnStatus != null && (obj.ScrSts == null || obj.ScrSts == ''));

              if (sec_total_filter.length > 0) { //cwsnStatus
                tot = sec_total_filter.length;
              }

              if (sec_scrn_filter.length > 0) { //cwsnStatus
                Scrn = sec_scrn_filter.length;
              }

              if (sec_unscrn_filter.length > 0) { //cwsnStatus
                Unscrn = sec_unscrn_filter.length;
              }

              this.sectionArr[i].tot = tot;
              this.sectionArr[i].Scrn = Scrn;
              this.sectionArr[i].Unscrn = Unscrn;
            }

            // this.schoolData = temp.map(l => { return { label: l.block_name, value: l.block_id }; });
            this.sectionArr.sort((a, b) => {
              if (a.Sec < b.Sec)
                return -1;
              if (a.Sec > b.Sec)
                return 1;
              return 0;
            });
            debugger

          } else {
            this.getSection();
          };
        });
      }
    })
  }

  onSync() {
    let query = 'DELETE FROM cwsn_sec_list' +
      ' WHERE school_key_id = "' + this.schoolId + '"' +
      ' And Class = "' + this.classId + '" ';
    this.sqliteDB.executeQuery(query).then(res => {
      if (res) {
        this.checkLocalDB();
      }
    });
  }

  selectSection(sectionData) {
    if (sectionData) {
      let queryData = {
        totalSclData: this.routeData.schoolId,
        clsSec: sectionData,
      };
      debugger
      this.router.navigate([`/tabs/cwsn/class-student-list/${this.schoolId}`], { queryParams: { data: JSON.stringify(queryData) }, skipLocationChange: true });
    }
  }

  getSection() {
    let query = 'SELECT * FROM AllClasslist' +
      ' WHERE SchlD = "' + this.schoolId + '"' +
      ' And ClsID = "' + this.classId + '" ';
    this.sqliteDB.executeQuery(query).then(res => {
      if (res.rows.length > 0) {
        let cls_temp = [];
        for (var i = 0; i < res.rows.length; i++) {
          cls_temp.push(res.rows.item(i));
        };
        let sqlArray = [];
        cls_temp.forEach(element => {
          element.tot = 0;
          element.Scrn = 0;
          element.Unscrn = 0;
          sqlArray.push(['INSERT INTO cwsn_sec_list VALUES (?,?,?,?,?,?,?)', [null, element.SchlD, element.ClsID, element.Sectn, element.tot, element.Scrn,
            element.Unscrn]]);
        });
        this.sqliteDB.bulkInsert(sqlArray).then((insertres) => {
          this.checkLocalDB();
        });
      } else {
        this.alertService.info('No Sections For Selected Class')
      }
    })
  }

  navigateBack() {
    let zonelId = localStorage.getItem('zonelId')
    this.router.navigate([`/tabs/cwsn/summary-list-cwsn/${zonelId}`], { queryParams: this.routeData.schoolId })
  }

}
